         @PayloadText = N'{"g":1,"subjectKind":"Device","inputs":["asset.formula.prc023_load_current","asset.formula.prc023_zset","device.protects.rating","device.settings.MTA","device.settings.R1","device.settings.X1"],"expressionText":"if(coalesce(asset.formula.prc023_load_current > 1.5 * device.protects.rating[kind=''FourHour''], false), ''1'', if(coalesce(asset.formula.prc023_load_current > 1.15 * device.protects.rating[kind=''FifteenMinute''], false), ''2'', if(coalesce(asset.formula.prc023_load_current > 1.15 * device.protects.rating[kind=''PracticalLimitation''], false), ''13'', if(coalesce(asset.formula.prc023_zset <= 1.25 * hypot(device.settings.R1, device.settings.X1) and device.settings.MTA = 90deg, false), ''12'', ''None''))))","expression":{"fn":"if","a":[{"fn":"coalesce","a":[{"op":">","l":{"fact":"asset.formula.prc023_load_current"},"r":{"op":"*","l":{"lit":"1.5","t":"num"},"r":{"fact":"device.protects.rating","p":{"kind":{"lit":"FourHour","t":"text"}}}}},{"lit":false,"t":"bool"}]},{"lit":"1","t":"text"},{"fn":"if","a":[{"fn":"coalesce","a":[{"op":">","l":{"fact":"asset.formula.prc023_load_current"},"r":{"op":"*","l":{"lit":"1.15","t":"num"},"r":{"fact":"device.protects.rating","p":{"kind":{"lit":"FifteenMinute","t":"text"}}}}},{"lit":false,"t":"bool"}]},{"lit":"2","t":"text"},{"fn":"if","a":[{"fn":"coalesce","a":[{"op":">","l":{"fact":"asset.formula.prc023_load_current"},"r":{"op":"*","l":{"lit":"1.15","t":"num"},"r":{"fact":"device.protects.rating","p":{"kind":{"lit":"PracticalLimitation","t":"text"}}}}},{"lit":false,"t":"bool"}]},{"lit":"13","t":"text"},{"fn":"if","a":[{"fn":"coalesce","a":[{"op":"and","a":[{"op":"<=","l":{"fact":"asset.formula.prc023_zset"},"r":{"op":"*","l":{"lit":"1.25","t":"num"},"r":{"fn":"hypot","a":[{"fact":"device.settings.R1"},{"fact":"device.settings.X1"}]}}},{"op":"=","l":{"fact":"device.settings.MTA"},"r":{"lit":"90","t":"num","u":"deg"}}]},{"lit":false,"t":"bool"}]},{"lit":"12","t":"text"},{"lit":"None","t":"text"}]}]}]}]},"publishes":{"fact":"asset.formula.prc023_criterion","type":"text"}}', @ActorId = @author, @VersionRowId = @v OUTPUT, @VersionNumber = @n OUTPUT;
    EXEC [config].[ApproveDefinitionVersion] @VersionRowId = @v, @ActorId = @approver;
